import{_ as t,c as s,o,j as a,a as l}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"周易义海撮要","description":"周易义海撮要 - 周易义海撮要","frontmatter":{"title":"周易义海撮要","description":"周易义海撮要 - 周易义海撮要"},"headers":[],"relativePath":"zh/classics/yihai-cuoyao/001.md","filePath":"zh/classics/yihai-cuoyao/001.md"}'),i={name:"zh/classics/yihai-cuoyao/001.md"};function r(c,e,n,p,d,u){return o(),s("div",null,[...e[0]||(e[0]=[a("h1",{id:"周易义海撮要",tabindex:"-1"},[l("周易义海撮要 "),a("a",{class:"header-anchor",href:"#周易义海撮要","aria-label":"Permalink to “周易义海撮要”"},"​")],-1),a("p",null,"钦定四库全书经部一",-1),a("p",null,"易类提要",-1),a("p",null,"臣等谨案：",-1),a("p",null,"周易义海撮要十二卷，宋李衡撰。衡字彦平，江都人。乾道中官秘阁修撰，寻除御史，改起居郎。事迹具宋史本传。先是，熙宁间，蜀人房审权病谈易诸家或泥阴阳，或拘象数，乃斥去杂学异说，摘取专明人事者百家，上起郑元，下迄王安石，编为一集，仍以孔颖达正义冠之。其有异同疑似，则各加评议，附之篇末，名曰周易义海共一百卷。衡因其义意重复，文词冗琐，删削厘定，以为此书，故名曰撮要。其程颐、苏轼、朱震三家之说，则原本未收，衡所续入。第十二卷杂论，亦衡所补缀。故婺州教授周汝能、楼锷跋称「卷计以百，今十有一」，盖耑指所删房本也。书录解题作十卷，又传写之误矣。是书成于绍兴三十年，至乾道六年，衡以御史守婺州，始锓于木。自唐以来，唯李鼎祚周易集解合汉后三十五家之说，略称该备，继之者审权、义海而已。然考宋史艺文志，但有衡书而无审权书。陈振孙书录解题亦惟载残本四卷。岂卷帙重大，当时即已散佚，抑冲书出而审权书遂废欤？然则采撷精华，使古书不没于后世，衡亦可谓有功矣。乾隆四十三年七月恭校上。总纂官 臣 纪昀、 臣 陆锡熊、 臣 孙士毅，总校官 臣 陆费墀。周易义海撮要原序：",-1),a("p",null,"易义海，熙宁间蜀人房审权所编。房谓自汉至今，专门学不啻千百家，或泥阴阳，或拘象数，或推之于互体，或失之于虚无。今于千百家内斥去杂学异说，摘取专明人事、羽翼吾道者仅百家，编为一集，仍以「正义」冠之端首，厘为百卷，目之曰周易义海。或诸家说有同异、理相疑惑者，复援父师之训、朋友之论，辄加评议，附之篇末。衡得是书而读之，其间尚有意义重叠、文词冗琐者，载加删削，而益之以伊川、东坡、汉上之说，庶学者便于观览云。绍兴庚辰十一月辛巳，江都李衡彦平遂安双清堂书。",-1)])])}const _=t(i,[["render",r]]);export{m as __pageData,_ as default};
